import 'package:flutter/material.dart';

// Avatar drawing data: the sprite / hair layers are long tables of path
// coordinates, kept apart from the profile screen on purpose.

enum OutfitStyleType {
  maleCasualTee,
  maleSuit,
  maleStripedTee,
  malePolo,
  maleHoodie,
  maleDenimJacket,
  maleSporty,
  maleOvercoat,
  maleVNeck,
  maleSweater,
  maleHawaiian,
  maleBikerJacket,
  maleOverall,
  maleVest,
  maleTuxedo,
  femaleWhiteShirt,
  femaleDress,
  femaleCropTop,
  femaleOffShoulder,
  femaleTurtleneck,
  femaleFloralDress,
  femaleOveralls,
  femaleBlazer,
  femaleHoodie,
  femaleKimono,
  femaleCardigan,
  femaleSporty,
  femalePastelTop,
  femaleEveningGown,
  femaleBoho,

  schoolUniform,
}

class OutfitItem {
  final String name;
  final OutfitStyleType type;
  final Color primaryColor;
  final Color secondaryColor;
  final String gender;

  const OutfitItem({
    required this.name,
    required this.type,
    required this.primaryColor,
    required this.secondaryColor,
    required this.gender,
  });
}

class HairItem {
  final String name;
  final int id;
  final String gender;

  const HairItem({required this.name, required this.id, required this.gender});
}

class AccessoryItem {
  final String name;
  final int id;
  final String type;

  const AccessoryItem({
    required this.name,
    required this.id,
    required this.type,
  });
}

class _SpriteLayer {
  final int fill;
  final int stroke;
  final double sw;
  final int flags;
  final List<double> d;
  const _SpriteLayer(this.fill, this.stroke, this.sw, this.flags, this.d);
}

class _HairLayer {
  final int kind;
  final double w;
  final List<double> d;
  const _HairLayer(this.kind, this.w, this.d);
}

class AvatarArt {
  static Offset _p(Rect r, double fx, double fy) =>
      Offset(r.left + fx * r.width, r.top + fy * r.height);
  static double _w(Rect r, double f) => f * r.width;
  static double _h(Rect r, double f) => f * r.height;

  static Color _darken(Color c, [double amt = 0.16]) {
    final HSLColor hsl = HSLColor.fromColor(c);
    return hsl.withLightness((hsl.lightness - amt).clamp(0.0, 1.0)).toColor();
  }

  static Color _lighten(Color c, [double amt = 0.16]) {
    final HSLColor hsl = HSLColor.fromColor(c);
    return hsl.withLightness((hsl.lightness + amt).clamp(0.0, 1.0)).toColor();
  }

  static List<Color> _palette(Color skin, Color hair, Color prim, Color sec) =>
      <Color>[
        Colors.transparent,
        skin,
        _darken(skin, 0.09),
        _darken(skin, 0.30),
        _lighten(skin, 0.07),
        hair,
        _darken(hair, 0.16),
        _lighten(hair, 0.14),
        prim,
        _darken(prim, 0.12),
        _darken(prim, 0.32),
        _lighten(prim, 0.10),
        sec,
        _darken(sec, 0.12),
        _darken(sec, 0.32),
        _lighten(sec, 0.10),
        const Color(0xFF3A2A25),
        Colors.white,
      ];

  static Path _spritePath(Rect r, List<double> d) {
    final Path p = Path();
    double X(double f) => r.left + f * r.width;
    double Y(double f) => r.top + f * r.height;
    int i = 0;
    while (i < d.length) {
      switch (d[i].toInt()) {
        case 0:
          p.moveTo(X(d[i + 1]), Y(d[i + 2]));
          i += 3;
          break;
        case 1:
          p.lineTo(X(d[i + 1]), Y(d[i + 2]));
          i += 3;
          break;
        case 2:
          p.quadraticBezierTo(
            X(d[i + 1]),
            Y(d[i + 2]),
            X(d[i + 3]),
            Y(d[i + 4]),
          );
          i += 5;
          break;
        case 3:
          p.cubicTo(
            X(d[i + 1]),
            Y(d[i + 2]),
            X(d[i + 3]),
            Y(d[i + 4]),
            X(d[i + 5]),
            Y(d[i + 6]),
          );
          i += 7;
          break;
        default:
          p.close();
          i += 1;
          break;
      }
    }
    return p;
  }

  static void _paintSprite(
    Canvas canvas,
    Rect r,
    List<_SpriteLayer> layers,
    List<Color> pal,
  ) {
    Color col(int v) => v < 64 ? pal[v] : Color(v);
    Path? lastMass;
    for (final _SpriteLayer l in layers) {
      final Path path = _spritePath(r, l.d);
      canvas.save();
      if ((l.flags & 2) != 0 && lastMass != null) canvas.clipPath(lastMass);
      if (l.fill != 0) {
        final Color fc = col(l.fill);
        final Paint fp = Paint()..color = fc;
        if ((l.flags & 1) != 0) {
          fp.shader = LinearGradient(
            begin: Alignment.topCenter,
            end: Alignment.bottomCenter,
            colors: [_lighten(fc, 0.05), _darken(fc, 0.06)],
          ).createShader(path.getBounds());
        }
        canvas.drawPath(path, fp);
      }
      if (l.stroke != 0) {
        canvas.drawPath(
          path,
          Paint()
            ..color = col(l.stroke)
            ..style = PaintingStyle.stroke
            ..strokeWidth = l.sw * r.width
            ..strokeCap = StrokeCap.round
            ..strokeJoin = StrokeJoin.round,
        );
      }
      canvas.restore();
      if ((l.flags & 4) != 0) lastMass = path;
    }
  }

  static void drawBodyAndOutfit(
    Canvas canvas,
    Rect r,
    Color skin,
    Color hair,
    OutfitItem outfit,
  ) {
    final List<Color> pal = _palette(
      skin,
      hair,
      outfit.primaryColor,
      outfit.secondaryColor,
    );
    canvas.save();
    canvas.clipRect(r);
    _paintSprite(canvas, r, _bodyLayers, pal);
    final int idx = outfit.type.index;
    if (idx >= 0 && idx < _outfitLayers.length) {
      _paintSprite(canvas, r, _outfitLayers[idx], pal);
    }
    canvas.restore();
  }

  static void drawHead(Canvas canvas, Rect r, Color skin, Color hair) {
    final List<Color> pal = _palette(skin, hair, Colors.white, Colors.white);
    _paintSprite(canvas, r, _earLayers, pal);
    _paintSprite(canvas, r, _headLayers, pal);
  }

  static void drawFace(
    Canvas canvas,
    Rect r,
    String gender,
    Color skin,
    Color hair,
  ) {
    final List<Color> pal = _palette(skin, hair, Colors.white, Colors.white);
    _paintSprite(
      canvas,
      r,
      gender == 'male' ? _faceLayersM : _faceLayersF,
      pal,
    );
  }

  static Path _hairPath(
    Offset c,
    double a,
    double b,
    List<double> d, {
    double dy = 0,
  }) {
    final Path p = Path();
    int i = 0;
    while (i < d.length) {
      final int op = d[i].toInt();
      switch (op) {
        case 0:
          p.moveTo(c.dx + d[i + 1] * a, c.dy + d[i + 2] * b + dy);
          i += 3;
          break;
        case 1:
          p.lineTo(c.dx + d[i + 1] * a, c.dy + d[i + 2] * b + dy);
          i += 3;
          break;
        case 2:
          p.quadraticBezierTo(
            c.dx + d[i + 1] * a,
            c.dy + d[i + 2] * b + dy,
            c.dx + d[i + 3] * a,
            c.dy + d[i + 4] * b + dy,
          );
          i += 5;
          break;
        case 3:
          p.cubicTo(
            c.dx + d[i + 1] * a,
            c.dy + d[i + 2] * b + dy,
            c.dx + d[i + 3] * a,
            c.dy + d[i + 4] * b + dy,
            c.dx + d[i + 5] * a,
            c.dy + d[i + 6] * b + dy,
          );
          i += 7;
          break;
        default:
          p.close();
          i += 1;
          break;
      }
    }
    return p;
  }

  static void _paintHairLayers(
    Canvas canvas,
    Rect r,
    List<_HairLayer> layers,
    Color color,
  ) {
    if (layers.isEmpty) return;
    final Offset c = _p(r, 0.5, 0.36);
    final double a = _w(r, 0.25);
    final double b = _h(r, 0.24);
    final Rect headRect = Rect.fromCenter(
      center: c,
      width: a * 2,
      height: b * 2,
    );
    final Color outlineColor = _darken(color, 0.30);
    final Color topTone = _lighten(color, 0.05);
    final Color bottomTone = _darken(color, 0.07);

    Paint stroke(Color col, double width) =>
        Paint()
          ..color = col
          ..style = PaintingStyle.stroke
          ..strokeWidth = width
          ..strokeCap = StrokeCap.round
          ..strokeJoin = StrokeJoin.round;

    Path? lastMass;
    for (final _HairLayer layer in layers) {
      switch (layer.kind) {
        case 0:
        case 8:
          final Path mass = _hairPath(c, a, b, layer.d);
          if (layer.kind == 8) {
            canvas.save();
            canvas.clipPath(Path()..addOval(headRect));
            canvas.drawPath(
              _hairPath(c, a, b, layer.d, dy: b * 0.075),
              Paint()..color = const Color(0x28000000),
            );
            canvas.restore();
          }
          final Rect bounds = mass.getBounds();
          canvas.drawPath(
            mass,
            Paint()
              ..shader = LinearGradient(
                begin: Alignment.topCenter,
                end: Alignment.bottomCenter,
                colors: [topTone, bottomTone],
              ).createShader(bounds),
          );
          canvas.drawPath(mass, stroke(outlineColor, _w(r, 0.0065)));
          lastMass = mass;
          break;
        case 5:
        case 6:
          final Color ac =
              layer.kind == 5
                  ? const Color(0xFFF472B6)
                  : const Color(0xFF475569);
          final Path tie = _hairPath(c, a, b, layer.d);
          canvas.drawPath(tie, Paint()..color = ac);
          canvas.drawPath(tie, stroke(_darken(ac, 0.25), _w(r, 0.005)));
          break;
        default:
          final Path detail = _hairPath(c, a, b, layer.d);
          canvas.save();
          if (lastMass != null) canvas.clipPath(lastMass);
          if (layer.kind == 1) {
            canvas.drawPath(detail, Paint()..color = _darken(color, 0.10));
          } else if (layer.kind == 2) {
            canvas.drawPath(
              detail,
              stroke(_darken(color, 0.17), _w(r, layer.w)),
            );
          } else if (layer.kind == 3) {
            canvas.drawPath(
              detail,
              stroke(const Color.fromARGB(80, 255, 255, 255), _w(r, layer.w)),
            );
          } else if (layer.kind == 4) {
            canvas.drawPath(
              detail,
              Paint()..color = const Color.fromARGB(70, 255, 255, 255),
            );
          }
          canvas.restore();
          break;
      }
    }
  }

  static void drawHairBack(
    Canvas canvas,
    Rect r,
    int hairId,
    Color color,
    String gender,
  ) {
    final List<List<_HairLayer>> table =
        gender == 'female' ? _femaleBackLayers : _maleBackLayers;
    if (hairId < 0 || hairId >= table.length) return;
    _paintHairLayers(canvas, r, table[hairId], color);
  }

  static void drawHairFront(
    Canvas canvas,
    Rect r,
    int hairId,
    Color color,
    String gender,
  ) {
    final List<List<_HairLayer>> table =
        gender == 'female' ? _femaleFrontLayers : _maleFrontLayers;
    if (hairId < 0 || hairId >= table.length) return;
    _paintHairLayers(canvas, r, table[hairId], color);
  }

